59	        boolean unique = Integer.valueOf(0).equals(owner.getNamesakeCount());
60	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
61	        return unique && hasEmail ? "SILVER" : "BRONZE";
